import{Lt as e,Vt as t,Z as n,_t as r,bt as i,mt as a,vt as o,yt as s}from"./chunks/framework.CsLlEPF4.js";import"./chunks/assets.Cofv-KFd.js";var c=JSON.parse(`{"title":"自定义 Zotero 数据存储位置","description":"","frontmatter":{"title":"自定义 Zotero 数据存储位置","date":"2025-04-12T00:00:00.000Z"},"headers":[],"relativePath":"user-guide/faqs/custom-data-directory.md","filePath":"wiki/user-guide/faqs/custom-data-directory.md"}`),l={name:`user-guide/faqs/custom-data-directory.md`};function u(n,c,l,u,d,f){let p=t(`Badge`),m=t(`NolebaseGitContributors`),h=t(`NolebaseGitChangelog`);return e(),r(`div`,null,[c[0]||=a(`div`,{style:{display:`none`},hidden:``,"data-nosnippet":``},`Are you an LLM? You can read better optimized documentation at /user-guidefaqscustom-data-directory.md for this page in Markdown format`,-1),c[1]||=a(`h1`,{id:`自定义-zotero-数据存储位置`,tabindex:`-1`},[s(`自定义 Zotero 数据存储位置 `),a(`a`,{class:`header-anchor`,href:`#自定义-zotero-数据存储位置`,"aria-label":`Permalink to “自定义 Zotero 数据存储位置”`},`​`)],-1),i(p,{text:`中级`}),c[2]||=o(`<p>Zotero 默认将所有文献条目、PDF、批注、笔记等存储在系统默认的「数据文件夹/Data Directory」（如 Windows 下的 <code>C:\\Users\\&lt;用户名&gt;\\Zotero</code>）。如果需要将数据迁移到其他位置（例如硬盘的其他分区），可以在设置里选择新的存储目录。</p><div class="danger custom-block"><p class="custom-block-title custom-block-title-default">危险</p><p>无论你选择何种同步方案，也无论基于何种原因，切勿将 Zotero 的 <code>数据存储位置/Data Directory</code> 自定义为任何网盘的同步文件夹中（包括 iCloud），也切勿使用任何网盘/同步盘的备份功能直接同步/备份这一目录!（包括但不限于直接使用坚果云的官方客户端直接同步备份这一文件夹）</p><p>这样做在某些情况下可能会导致你的 Zotero 数据库损坏，带来严重的问题！官方对于这一问题的说明见这两篇文章：</p><ul><li><a href="https://www.zotero.org/support/sync#alternative_syncing_solutions" target="_blank" rel="noreferrer">How can I access my library from multiple computers?</a></li><li><a href="https://www.zotero.org/support/kb/data_directory_in_cloud_storage_folder" target="_blank" rel="noreferrer">Can I store my Zotero data directory in a cloud storage folder?</a></li></ul><p>如果您已经将 Zotero 数据文件夹直接同步到网盘中，请您做好<a href="./../backup#手动备份">备份</a>，根据下面的教程将数据文件夹迁移到本地的其他位置，且确保未使用任何工具直接同步这一数据文件夹。</p></div><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to “操作步骤”">​</a></h2><ol><li><p><strong>打开 Zotero 设置</strong></p><p>点击 Zotero 的 <code>编辑</code> → <code>设置</code> → <code>高级</code>，在 <code>文件和文件夹</code> 中的 <code>数据存储位置</code> 可以看到当前的数据文件夹位置。点击 <code>打开数据文件夹</code> 按钮打开待迁移的数据文件夹备用。</p><p><img src="/assets/zotero-custom-data-directory.CSj0Omeg.png" alt="打开数据文件夹" width="802" height="632"></p><div class="tip custom-block"><p class="custom-block-title">提醒</p><p>在继续下面的操作前，建议您先备份当前的数据文件夹，避免数据丢失。您可以将待迁移的数据文件夹中的所有内容复制到其他位置，以备不时只需。<br> 关于备份的更多介绍，请参考：<a href="./../backup">Zotero 备份教程</a>。</p></div></li><li><p><strong>选择新的数据目录</strong></p><p>点击 <code>数据存储位置</code> 中的 <code>使用自定义位置</code>按钮，在弹出的对话框中您希望放置数据文件夹的位置，然后点击对话框中的 <code>新建文件夹</code> 按钮创建新的数据文件夹，在对话框中打开新创建好的数据文件夹，点击 <code>确定</code>。</p><p><img src="/assets/zotero-custom-data-directory-select.BSzKZPQf.png" alt="选择新的数据目录" width="946" height="533"></p><details class="details custom-block"><summary>数据目录放置位置的建议</summary><p>如果将数据目录放在不合适的位置，可能会因权限问题导致 Zotero 出现故障。以下是一些提醒和建议：</p><ul><li><strong>切勿将数据目录放在任何网盘的同步文件夹中（包括 iCloud），也切勿使用任何网盘/同步盘的备份功能直接同步/备份这一目录！</strong></li><li>不要将数据目录放在 Zotero 的程序安装目录下（如默认的 <code>C:\\Program Files\\Zotero</code>），也不要将数据目录选为 Zotero 的程序安装目录，避免文件混乱和权限问题。</li><li>可以放在 <code>D:\\ZoteroDataDirectory</code> 或 <code>E:\\Data\\ZoteroData</code> 等 <strong>非系统盘</strong> 的目录下，避免权限问题。</li><li>数据目录的路径和文件夹名中不建议包含中文、空格或特殊字符，避免一些兼容问题。（如不建议将路径设置为 <code>D:\\学术\\Zotero Data</code> 或 <code>D:\\My Data\\Zotero Data</code>，您可以改为 <code>D:\\Scholar\\ZoteroData</code> 或 <code>D:\\MyData\\ZoteroData</code>）</li></ul></details><p>选择完新创建的空目录后，Zotero 会提示您目录为空。请点击 <code>是/Yes</code> 按钮。</p><p><img src="/assets/zotero-custom-data-directory-info1.CCPxMLxU.png" alt="移动数据文件夹提醒" width="647" height="169"></p></li><li><p><strong>关闭 Zotero</strong></p><p>在设置完成后，Zotero 会提醒退出 Zotero 程序。请点击 <code>退出 Zotero</code> 按钮，关闭 Zotero 程序。</p><p><img src="/assets/zotero-custom-data-directory-info2.C3Q0TjRA.png" alt="关闭 Zotero" width="632" height="151"></p></li><li><p><strong>手动移动已有数据</strong></p><p>请前往第 1 步中打开备用的待迁移数据文件夹，将原数据文件夹中的<strong>所有内容</strong>（包含 <code>zotero.sqlite</code> 文件、<code>storage</code> 文件夹等）拷贝到新数据目录下。</p><p><img src="/assets/zotero-custom-data-directory-move-data.zsJnND0n.png" alt="手动移动已有数据" width="1663" height="593"></p><div class="tip custom-block"><p class="custom-block-title">提醒</p><p>数据迁移完成之前，请勿打开 Zotero 程序。</p></div></li><li><p><strong>重新打开 Zotero</strong></p><p>重新打开 Zotero，检查文库中的文献是否齐全，附件是否可以正常打开。</p></li><li><p><strong>完成迁移</strong></p><p>如果一切正常，您已经成功将 Zotero 的数据目录迁移到新的位置。确认迁移完成且数据完整后，可以删除原数据目录下的文件。但建议先保留一段时间，直到确定迁移的数据无误。</p><div class="tip custom-block"><p class="custom-block-title">提醒</p><p>如果迁移后无法正常使用 Zotero，您也可以将数据目录的设置恢复到原来的位置，Zotero 会自动识别并使用原来的数据目录。</p></div></li></ol><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><ul><li><strong>不要将数据目录直接设置在任何云盘同步文件夹下</strong>，避免数据库损坏。</li><li>迁移完成后，如果出现无法打开 Zotero、看不到文献、无法找到附件等问题，请再次检查目标文件夹中的文件是否完整复制，以及 Zotero 设置中的目录路径是否指向这一新位置。</li><li>自定义数据文件夹时，无需搬迁用户配置文件，仅移动数据文件夹即可。用户配置文件夹建议保留在默认位置。</li><li>如果您使用 <code>Attanger/ZotMoov + 同步盘</code> 的同步方案，请不要手动移动用于异地存放附件的 <code>靶目录</code>，避免出现找不到的情况。同时，也不建议将 <code>靶目录</code> 设置在 Zotero 数据文件夹下，也不要将自定义的 Zotero 数据文件夹选为 <code>靶目录</code> 或放置在 <code>靶目录</code> 下，避免出现文件混乱。</li></ul>`,6),i(m),i(h)])}var d=n(l,[[`render`,u]]);export{c as __pageData,d as default};